glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec2 a_uv0;
out vec2 v_uv0;
void main () {
  vec4 pos = vec4(a_position, 1.0);
  pos = cc_matViewProj * cc_matWorld * pos;
  v_uv0 = a_uv0;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
in vec2 v_uv0;
uniform sampler2D texture;
  float rand(vec2 co) {
    return fract(sin(dot(co.xy , vec2(12.9898, 78.233))) * 43758.5453);
  }
  vec4 blur(vec2 uv){
        float _blurAmount = 0.04;
    vec3 blurred = vec3(0.0);
    for(float i = 0.0; i < 6.0; i ++ )
    {
      vec2 q = vec2(cos(degrees((i / 6.0) * 360.0)), sin(degrees((i / 6.0) * 360.0))) * (rand(vec2(i, uv.x + uv.y)) + _blurAmount);
      vec2 uv2 = uv + (q * _blurAmount+0.5);
      blurred += texture2D(texture, uv).rgb / 2.0;
      q = vec2(cos(degrees((i / 6.0) * 360.0)), sin(degrees((i / 6.0) * 360.0))) * (rand(vec2(i + 2.0, uv.x + uv.y + 24.0)) + _blurAmount);
      uv2 = uv + (q * _blurAmount);
      blurred += texture2D(texture, uv2).rgb / 2.0;
    }
    blurred /= 6.0;
    return vec4(blurred,texture2D(texture, uv).a);
  }
  void main()
  {
    gl_FragColor = vec4(blur(v_uv0));
  }

